<script lang="ts">import { onMount } from 'svelte';import gsap from 'gsap';import type { VocabularyEntry } from '../../api/types';import CardFront from './CardFront.svelte';import CardBack from './CardBack.svelte';let { entry,revealed,onreveal,oncounts }=$props<{entry:VocabularyEntry;revealed:boolean;onreveal:()=>void;oncounts:(c:number,e:number)=>void}>();let shell:HTMLDivElement;onMount(()=>gsap.from(shell,{y:10,opacity:0,duration:.24,ease:'power2.out'}));$effect(()=>{revealed;if(shell)gsap.fromTo(shell,{scale:.992,opacity:.75},{scale:1,opacity:1,duration:.24,ease:'power2.out'})});</script>
<div class="shell" bind:this={shell}>{#if revealed}<CardBack {entry} {oncounts}/>{:else}<CardFront {entry} {onreveal}/>{/if}</div>
